package com.soumya.walletwise.auth;
import com.fasterxml.jackson.databind.ObjectMapper; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*;
final class Jwt { private final String secret; private final long expiry; private final ObjectMapper json=new ObjectMapper(); Jwt(String secret,long expiry){this.secret=secret;this.expiry=expiry;} String issue(User u){try{String h=b64("{\"alg\":\"HS256\",\"typ\":\"JWT\"}"), p=b64(json.writeValueAsString(Map.of("sub",u.id,"email",u.email,"role",u.role,"exp",Instant.now().getEpochSecond()+expiry)));return h+"."+p+"."+sign(h+"."+p);}catch(Exception e){throw new IllegalStateException(e);}} @SuppressWarnings("unchecked") Map<String,Object> verify(String t){try{String[] s=t.split("\\.");if(s.length!=3||!sign(s[0]+"."+s[1]).equals(s[2]))throw new IllegalArgumentException();Map<String,Object> p=json.readValue(Base64.getUrlDecoder().decode(s[1]),Map.class);if(((Number)p.get("exp")).longValue()<Instant.now().getEpochSecond())throw new IllegalArgumentException();return p;}catch(Exception e){throw new IllegalArgumentException("Invalid or expired token");}} private String sign(String v)throws Exception{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(m.doFinal(v.getBytes(StandardCharsets.UTF_8)));} private String b64(String v){return Base64.getUrlEncoder().withoutPadding().encodeToString(v.getBytes(StandardCharsets.UTF_8));}}
